-- GUIMMIA V76.7 - 148 operational rules
on conflict(code) do update set title=excluded.title,priority=excluded.priority,sort_order=excluded.sort_order,active=true,updated_at=now();

update public.guimmia_brain_workflows set active=false,updated_at=now() where slug in ('rent-long-term-residential','rent-transitory-residential','rent-student-residential','rent-tourist-short') and version<>2 and active;

